	@Test
	void exactStarBagCardinalityIsEight() {
		OracleBag firstArm = OracleBag.empty()
				.plus(binding("s", 1L, "x", 11L), 1)
				.plus(binding("s", 1L, "x", 12L), 1)
				.plus(binding("s", 2L, "x", 13L), 1);
		OracleBag secondArm = OracleBag.empty()
				.plus(binding("s", 1L, "y", 21L), 1)
				.plus(binding("s", 1L, "y", 22L), 1)
				.plus(binding("s", 1L, "y", 23L), 1)
				.plus(binding("s", 2L, "y", 24L), 1)
				.plus(binding("s", 2L, "y", 25L), 1);

		assertEquals(ExactRational.of(8), ExactRational.of(firstArm.naturalJoin(secondArm).cardinality()));
	}

