		OracleSamplingDesign<OracleWeightedMeasure<String>> design = OracleSamplingDesign.of(List.of(
				OracleSamplingDesign.outcome(ExactRational.of(1, 16), measure("a", 4)),
				OracleSamplingDesign.outcome(ExactRational.of(6, 16), measure("a", 2, "b", 2)),
				OracleSamplingDesign.outcome(ExactRational.of(9, 16), measure("b", 4))));

		assertEquals(ExactRational.of(1), design.expectation(state -> state.weight("a")));
		assertEquals(ExactRational.of(3), design.expectation(state -> state.weight("b")));
