	private static ExactRational delayedRewardRelativeVariance(int paths, int particles) {
		OracleSamplingDesign.requireParticleCapacity(particles);
		return ExactRational.of(paths - 1, particles);
	}

	private static OracleWeightedMeasure<String> exactTransfer(OracleWeightedMeasure<String> source,
			Map<String, Map<String, ExactRational>> bridge) {
		OracleWeightedMeasure<String> result = OracleWeightedMeasure.empty();
		for (Map.Entry<String, ExactRational> sourceEntry : source.weights().entrySet()) {
			Map<String, ExactRational> adjacency = bridge.getOrDefault(sourceEntry.getKey(), Map.of());
			for (Map.Entry<String, ExactRational> edge : adjacency.entrySet()) {
				result = result.plus(edge.getKey(), sourceEntry.getValue().multiply(edge.getValue()));
			}
		}
		return result;
	}

	private static OracleWeightedMeasure<String> measure(Object... keyWeights) {
		OracleWeightedMeasure<String> result = OracleWeightedMeasure.empty();
		for (int index = 0; index < keyWeights.length; index += 2) {
			result = result.plus((String) keyWeights[index],
					ExactRational.of(((Number) keyWeights[index + 1]).longValue()));
		}
		return result;
	}

	private static Map<String, ExactRational> edges(Object... keyWeights) {
		java.util.LinkedHashMap<String, ExactRational> result = new java.util.LinkedHashMap<>();
		for (int index = 0; index < keyWeights.length; index += 2) {
			result.put((String) keyWeights[index], ExactRational.of(((Number) keyWeights[index + 1]).longValue()));
		}
		return Map.copyOf(result);
	}

	private static OracleBinding binding(Object... values) {
		java.util.LinkedHashMap<String, Long> result = new java.util.LinkedHashMap<>();
		for (int index = 0; index < values.length; index += 2) {
			result.put((String) values[index], (Long) values[index + 1]);
		}
		return OracleBinding.of(result);
	}
